        "text": "Базовый эффект навыка. Каждое вложенное очко даёт +1 к итоговому значению навыка и +1 к урону обычных ударов без оружия. Бонус к навыку учитывается в проверке один раз. Захваты, толчки и другие действия без урона не получают повреждений от этого бонуса."
