        "text": "Ритуал; 1 минута, 5 Живы и подходящий труп. Призывает одну Малую тень по карточке на 10 минут; цена Тлена сохраняется. Это отдельное книжное умение «Призыв тени», не часовой ритуал «Призыв теней» 3-й ступени. Тень учитывается в общем пределе призванных духов; неподходящие призывы не превращаются в источник трупов. Школьная скидка заклинаний к цене этого отдельного умения автоматически не применяется. Один ранг за 1 очко."
