        "kind": "paragraph",
        "text": "На «1» урон максимальный и выбирается один эффект: благоволение, подходящее свойство оружия либо Правь. Успешный дубль наносит обычный урон и даёт один эффект Яви либо подходящее свойство оружия. «100» проваливает ударную часть и даёт один эффект Нави. Одна проверка серии не вызывает таблицу отдельно за каждый описанный удар. Противники используют собственную формулу попадания и число атак из карточки; человеческие серии им автоматически не выдаются."
